import type { Scope } from "@tinker/core";

/** The main retains named roots in start order and stop controllers with the same names; repeated close calls share one promise. */
export function createScopeClose<T extends Record<string, Scope.RootHandle>>(
  roots: T,
  stop: Record<keyof T, AbortController>,
): () => Promise<void> {
  let closed: Promise<void> | undefined;
  return function close() {
    return (closed ??= closeRoots(roots, stop));
  };
}

async function closeRoots(
  roots: Record<string, Scope.RootHandle>,
  stop: Record<string, AbortController>,
): Promise<void> {
  const closedReason = new DOMException("The server closed", "AbortError");
  const results: Scope.Result[] = [];
  for (const [name, scope] of Object.entries(roots).toReversed()) {
    stop[name].abort(closedReason);
    results.push(await scope.closed);
  }

  for (const result of results) {
    if (result.status === "failed") throw result.error;
    if (result.teardownErrors?.length) throw result.teardownErrors.at(0);
  }
}

import { tag } from "@tinker/core";
import type { Observe } from "@tinker/core";

/** The command binds render observation; each request borrows it from its own app root. */
export const renderObservation = tag<Observe.Config | undefined>({
  label: "start.renderObservation",
  default: undefined,
});

import { inspect } from "node:util";

import type { ServerEntry } from "./server-entry";

/** Report unhandled process work and close the main before exit; this starts no root. */
export function observeServerPanics(entry: ServerEntry.Handle): void {
  const fail = async (error: unknown) => {
    process.stderr.write(`server: unhandled rejection ${inspect(error)}\n`);
    try {
      await entry.close();
    } finally {
      process.exit(1);
    }
  };

  process.on("unhandledRejection", fail);
  entry.requestContext.scope.onClose(() => {
    process.off("unhandledRejection", fail);
  });
}

import type { ErrorComponentProps } from "@tanstack/react-router";

/**
 * Dev only. Start answers a failed render with a bare JSON 500, and that page has no Vite
 * client, so it never sees the fix. This page keeps the body and reloads on the next update.
 * @param request - From the server entry; why: only a browser page load gets the HTML page.
 * @param response - From Start; why: every other response passes through untouched.
 */
export async function devErrorPage(request: Request, response: Response): Promise<Response> {
  const page = request.headers.get("accept")?.includes("text/html");
  const json = response.headers.get("content-type")?.includes("application/json");
  if (response.status !== 500 || !page || !json) return response;
  const body = (await response.text()).replaceAll("&", "&amp;").replaceAll("<", "&lt;");
  return new Response(
    `<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <title>Error</title>
    <script type="module">
      import { createHotContext } from "/@vite/client";
      createHotContext("/@tinker/dev-error").on("vite:beforeUpdate", () => location.reload());
    </script>
  </head>
  <body>
    <pre>${body}</pre>
    <p>tinker: the page failed to render; the error is in the terminal.</p>
    <p>Save a fix and this page reloads.</p>
  </body>
</html>`,
    { status: 500, headers: { "content-type": "text/html; charset=utf-8" } },
  );
}

/**
 * The base's error page: a production page shows no error text, and the server log gets the
 * error. It logs to the console because this POC base has no telemetry part yet.
 */
export function TinkerError({ error }: ErrorComponentProps) {
  if (import.meta.env.SSR) console.error("tinker: a route failed on the server:", error);
  return <ErrorDetails error={error} dev={import.meta.env.DEV} />;
}

/** Show the error text only when the entry is in dev mode. */
export function ErrorDetails({ error, dev }: { error: unknown; dev: boolean }) {
  const detail = dev ? (error instanceof Error ? error.message : String(error)) : undefined;

  return (
    <main>
      <h1>Something went wrong</h1>
      {detail !== undefined && <pre>{detail}</pre>}
    </main>
  );
}

/** The base's 404 page; a route's own notFoundComponent, or src/router.ts, replaces it. */
export function TinkerNotFound() {
  return (
    <main>
      <h1>Not found</h1>
    </main>
  );
}

import { createRouter } from "@tanstack/react-router";
import type { RouterConstructorOptions, RouterHistory } from "@tanstack/react-router";
import { createIsomorphicFn, getGlobalStartContext } from "@tanstack/react-start";
import { createScope } from "@tinker/core";
import type { Many, Scope } from "@tinker/core";
import { ScopeProvider } from "@tinker/react";

import { abortReasons } from "~/components/errors";

import { renderObservation } from "./observe";
import { TinkerError, TinkerNotFound } from "./panics";

export type RouteTree = (typeof import("#tinker/routes"))["routeTree"];

export type RouterOptions = Partial<
  Omit<
    RouterConstructorOptions<RouteTree, "never", false, RouterHistory, Record<string, unknown>>,
    "routeTree" | "Wrap" | "context"
  >
>;

type Parts = Pick<
  Awaited<ReturnType<(typeof import("@tinker/start/router"))["loadRouterParts"]>>,
  "sync" | "telemetry" | "pageEvents" | "tabStop"
>;

/** Bind optional parts now; load the route tree only when Start requests a router. */
export function createRouterEntry({
  parts,
  extensions,
  router,
}: {
  parts: Parts | (() => Promise<Parts>);
  extensions: Many<Scope.Extension<unknown>>;
  router: RouterOptions;
}) {
  return async function getRouter() {
    const { sync, telemetry, pageEvents, tabStop } =
      typeof parts === "function" ? await parts() : parts;
    const { routeTree } = await import("#tinker/routes");

    const readTelemetry = createIsomorphicFn()
      .server(() => ({
        observe: () => getGlobalStartContext()?.scope?.resolve(renderObservation),
        close: undefined,
      }))
      .client(async () => {
        const toolStop = new AbortController();
        const tools = createScope({
          signal: toolStop.signal,
          extensions: telemetry.extensions,
          tags: telemetry.tags,
        });
        await tools.ready;
        return {
          observe() {
            return tools.resolve(telemetry.observe);
          },
          close() {
            toolStop.abort(abortReasons.closed);
            return tools.closed;
          },
        };
      });

    const readPage = createIsomorphicFn()
      .server((): EventTarget | undefined => undefined)
      .client(() => window);

    const reading = readTelemetry();
    const tools = reading instanceof Promise ? await reading : reading;

    const stop = new AbortController();
    const app = createScope({
      signal: stop.signal,
      extensions: [sync.extensions, extensions],
      observe: tools.observe(),
      tags: [tabStop(stop.signal), pageEvents(readPage())],
    });

    let tab: Awaited<ReturnType<typeof sync.router.factory>>;
    try {
      await app.ready;
      tab = app.resolve(sync.router);
    } catch (error) {
      stop.abort(abortReasons.closed);
      await app.closed;
      await tools.close?.();
      throw error;
    }

    let closed: Promise<void> | undefined;
    async function finishClose() {
      stop.abort(abortReasons.closed);
      const end = await app.closed;
      const toolEnd = await tools.close?.();
      for (const result of [end, toolEnd]) {
        if (result?.status === "failed") throw result.error;
        if (result?.teardownErrors?.length) throw result.teardownErrors.at(0);
      }
    }

    const close = () => (closed ??= finishClose());

    tab.bind(close);
    if (import.meta.hot) import.meta.hot.dispose(close);

    return Object.assign(
      createRouter({
        scrollRestoration: true,
        defaultErrorComponent: TinkerError,
        defaultNotFoundComponent: TinkerNotFound,
        ...router,
        ...tab.options,
        routeTree,
        Wrap: ({ children }) => <ScopeProvider scope={app}>{children}</ScopeProvider>,
      }),
      { close },
    );
  };
}

/** TanStack binds route types to the copied router entry. */
declare module "@tanstack/react-router" {
  interface Register {
    router: Awaited<ReturnType<ReturnType<typeof createRouterEntry>>>;
  }
}

import {
  createStartHandler as createStart,
  defaultStreamHandler as renderStream,
} from "@tanstack/react-start/server";
import type { Scope } from "@tinker/core";

import { raise } from "~/components/errors";
import { renderFrames } from "~/components/requests/index.server";

import { devErrorPage } from "./panics";
import type { createRouterEntry } from "./router-entry";

/** The command retains both roots; Start borrows context and observation. */
export declare namespace ServerEntry {
  type Next = (request: Request) => Promise<Response>;
  type Handle = {
    requestContext: { scope: Scope.Handle };
    close(): Promise<void>;
    fetch?(request: Request, next: Next): Promise<Response> | Response;
  };
}

/** Render over the supplied app; request bodies retain each render's close. */
export function createServerHandler(app: ServerEntry.Handle) {
  const renderRequest = createStart(async (context) => {
    const router: typeof context.router & {
      close?: Awaited<ReturnType<ReturnType<typeof createRouterEntry>>>["close"];
    } = context.router;
    if (typeof router.close !== "function") raise("StartScopeMissing", {});
    app.requestContext.scope.resolve(renderFrames).retain(context.request, router.close);

    try {
      return await renderStream(context);
    } catch (error) {
      await router.close();
      throw error;
    }
  });

  return {
    ...app,
    fetch(request: Request) {
      const next = async (forwarded: Request) => {
        const response = await renderRequest(forwarded, { context: app.requestContext });
        return import.meta.env.DEV ? devErrorPage(forwarded, response) : response;
      };
      return app.fetch ? app.fetch(request, next) : next(request);
    },
  };
}

import { createCsrfMiddleware, createStart } from "@tanstack/react-start";

import { startRequests } from "~/components/requests";

/** The command passes app options; CSRF and requests run before its middleware. */
export function createStartEntry(app: { getOptions: Parameters<typeof createStart>[0] }) {
  const csrf = createCsrfMiddleware({ filter: (ctx) => ctx.handlerType === "serverFn" });
  let options: ReturnType<typeof readOptions> | undefined;

  async function readOptions() {
    const own = await app.getOptions();
    return {
      ...own,
      requestMiddleware: [csrf, startRequests.middleware, ...(own.requestMiddleware ?? [])],
    };
  }

  return createStart(() => (options ??= readOptions()));
}

import { createStartEntry } from "~/base/start-entry";

import { startInstance as app } from "@/start";

export const startInstance = createStartEntry(app);

import { createStart } from "@tanstack/react-start";

/** The command reads this app-owned Start setup; keep it even when options are empty. */
export const startInstance = createStart(() => ({}));

import type { Tag } from "@tinker/core";

export declare namespace Env {
  /** The process environment, as the server entry copies it once. */
  type Values = Readonly<Record<string, string | undefined>>;
  /**
   * How env becomes typed settings tags at the scope's door (ADR 0113): the server seam's
   * `settings`, and each base part's. No unit depends on env.
   */
  type Read = (env: Values) => Tag.Bindings;
}

export declare namespace Errors {
  type Payloads = {
    HttpRequestFailed: {
      method: string;
      path: string;
      cause?: { name?: string; code?: string | number };
    };
    StartScopeMissing: Record<string, never>;
    Cancelled: Record<string, never>;
    BadSettings: { part: string; keys: string[] };
    StreamMissing: Record<string, never>;
    StreamDenied: Record<string, never>;
    StreamDisconnected: Record<string, never>;
    WriteRejected: { message: string };
  };
  type Name = keyof Payloads;
  type Of<N extends Name> = Error & { kind: N; payload: Payloads[N] };
}

/**
 * @param kind - From a failed base action; why: choose the managed error.
 * @param payload - From that action; why: keep its failure facts.
 */
export function raise<N extends Errors.Name>(kind: N, payload: Errors.Payloads[N]): never {
  throw fail(kind, payload);
}

/**
 * The managed error itself, for a caller that rejects a promise with it instead of throwing.
 * @param kind - From a failed base action; why: choose the managed error.
 * @param payload - From that action; why: keep its failure facts.
 */
export function fail<N extends Errors.Name>(kind: N, payload: Errors.Payloads[N]): Errors.Of<N> {
  return Object.assign(new Error(kind), { kind, payload });
}

/**
 * @param error - From a caught failure; why: narrow its payload.
 * @param kind - From the caller; why: select the expected error.
 */
export function isError<N extends Errors.Name>(error: unknown, kind: N): error is Errors.Of<N> {
  return error instanceof Error && "kind" in error && error.kind === kind;
}

/** Abort consumers keep the native AbortError name and code without a per-call stack. */
export const abortReasons = {
  closed: new DOMException("The owner closed", "AbortError"),
  changed: new DOMException("The account changed", "AbortError"),
  done: new DOMException("The wait ended", "AbortError"),
  timeout: new DOMException("The deadline passed", "AbortError"),
};

export { raise, fail, isError, abortReasons } from "./errors";
export type { Errors } from "./errors";
export type { Env } from "./env";

import { resource } from "@tinker/core";

import { startServer } from "./modules.server";

/** Retains request work until the consumer ends, fails, or cancels the body. */
export const responseBodies = resource({
  label: "start.responseBodies",
  target: "scope",
  depends: { startServer },
  factory: async ({ startServer }, ctx) => {
    const readers = new Set<{
      reader: ReadableStreamDefaultReader<Uint8Array>;
      finish: (graceful: boolean) => Promise<void>;
      cancelled: boolean;
    }>();
    ctx.defer(async () => {
      const results = await Promise.allSettled(
        [...readers].map(async (owned) => {
          owned.cancelled = true;
          readers.delete(owned);
          const ended = await Promise.allSettled([owned.reader.cancel(), owned.finish(false)]);
          for (const result of ended) if (result.status === "rejected") throw result.reason;
        }),
      );
      for (const result of results) if (result.status === "rejected") throw result.reason;
    });
    return {
      isResponse(value: unknown): value is Response {
        return value instanceof Response;
      },
      hold(
        response: Response,
        finish: (graceful: boolean) => Promise<void>,
      ): Response | Promise<Response> {
        if (response.body === null) {
          return finish(true).then(() => response);
        }

        const reader = response.body.getReader();
        const owned = { reader, finish, cancelled: false };
        readers.add(owned);

        const body = new ReadableStream<Uint8Array>({
          async pull(controller) {
            try {
              const part = await reader.read();
              if (part.done) {
                readers.delete(owned);
                await finish(!owned.cancelled);
                if (!owned.cancelled) controller.close();
              } else if (!owned.cancelled) controller.enqueue(part.value);
            } catch (error) {
              readers.delete(owned);
              await finish(false);
              if (!owned.cancelled) controller.error(error);
            }
          },
          async cancel(reason) {
            owned.cancelled = true;
            readers.delete(owned);
            const results = await Promise.allSettled([finish(false), reader.cancel(reason)]);
            for (const result of results) {
              if (result.status === "rejected") throw result.reason;
            }
          },
        });

        return startServer.transferResponseBodyOwnership(
          response,
          new Response(body, {
            status: response.status,
            statusText: response.statusText,
            headers: response.headers,
          }),
        );
      },
    };
  },
});

import { tag } from "@tinker/core";

/** Only request wiring and auth borrow the raw headers; app operations use principal. */
export const requestHeaders = tag<Headers>({ label: "request.headers" });

export { startRequests, backendStop, requestStop } from "./index";
export { readResult } from "./result.server";
export { requestHeaders } from "./headers.server";
export { requestBody } from "./request-body.server";
export { responseBodies } from "./body.server";
export { renderLifetime, renderFrames } from "./render-lifetime.server";

import { tag } from "@tinker/core";

/** The main supplies its host signal before graceful drain joins held requests. */
export const backendStop = tag<AbortSignal>({ label: "lifetime.backendStop" });

export const requestStop = tag<AbortSignal>({ label: "lifetime.requestStop" });

import { resource } from "@tinker/core";

export const startServer = resource({
  label: "module:@tanstack/react-start/server",
  target: "scope",
  factory: () => import("@tanstack/react-start/server"),
});

import { resource } from "@tinker/core";

import { raise } from "~/components/errors";

/** The app owns the lookup; each request session owns its render close. */
export const renderFrames = resource({
  label: "request.renders",
  target: "scope",
  factory: () => {
    const renders = new WeakMap<Request, { close: (() => Promise<void>) | undefined }>();

    return {
      open(request: Request) {
        const owned = { close: undefined as (() => Promise<void>) | undefined };
        renders.set(request, owned);
        return owned;
      },
      release(request: Request) {
        renders.delete(request);
      },
      retain(request: Request, close: () => Promise<void>) {
        const owned = renders.get(request);
        if (owned === undefined) raise("StartScopeMissing", {});
        owned.close = close;
      },
    };
  },
});

/** The request retains render work until its body ends. */
export const renderLifetime = resource({
  label: "request.renderLifetime",
  target: "session",
  depends: { renders: renderFrames },
  factory: ({ renders }, ctx) => {
    let owned: { close: (() => Promise<void>) | undefined } | undefined;
    let request: Request | undefined;
    ctx.defer(() => {
      if (request) renders.release(request);
      request = undefined;
      const close = owned?.close;
      if (owned) owned.close = undefined;
      return close?.();
    });

    return {
      open(value: Request) {
        request = value;
        owned = renders.open(value);
      },
    };
  },
});

import { resource } from "@tinker/core";

import { backendStop, requestStop } from "./lifetime";

/** The request owns the reader; its route borrows it until all body checks finish. */
export const requestBody = resource({
  label: "request.body",
  target: "session",
  depends: { backendStop, requestStop },
  factory: ({ backendStop, requestStop }, ctx) => {
    const signal = AbortSignal.any([backendStop, requestStop, ctx.signal]);
    let reader: ReadableStreamDefaultReader<Uint8Array<ArrayBuffer>> | undefined;
    let cancellation: Promise<void> | undefined;

    const cancel = () => {
      cancellation ??= reader?.cancel();
    };
    signal.addEventListener("abort", cancel, { once: true });

    const release = async () => {
      signal.removeEventListener("abort", cancel);
      if (signal.aborted) cancel();
      await cancellation;
      reader?.releaseLock();
      reader = undefined;
    };
    ctx.defer(release);

    return {
      signal,
      open(body: ReadableStream<Uint8Array<ArrayBuffer>>) {
        reader = body.getReader();
        if (signal.aborted) cancel();
        return reader;
      },
      release,
    };
  },
});

import type { RunResult } from "@tinker/core";

import { fail } from "~/components/errors";

/** HTTP boundaries handle a settled failure without failing the server root.
 * @param result - From a settled boundary call; why: return its value or raise its failure.
 */
export function readResult<T>(result: RunResult<T>): T {
  if (result.status === "failed") throw result.error;
  if (result.status === "cancelled") throw fail("Cancelled", {});
  return result.value;
}

import { createMiddleware } from "@tanstack/react-start";
import { extension } from "@tinker/core";
import type { Scope } from "@tinker/core";

import { raise } from "~/components/errors";

import { responseBodies } from "./body.server";
import { requestHeaders } from "./headers.server";
import { requestStop } from "./lifetime";
import { requestClose, requestLifetime } from "./lifetime.server";
import { renderLifetime } from "./render-lifetime.server";

/** Start merges this registry to type the context supplied by the server entry. */
declare module "@tanstack/react-start" {
  interface Register {
    server: { requestContext: { scope?: Scope.Handle } };
  }
}

/** This root middleware uses only fetch context, before global middleware has run. */
const middleware = createMiddleware().server(async ({ context, request, next }) => {
  const scope = context.scope;
  if (scope === undefined) raise("StartScopeMissing", {});

  const session = scope.createSession({
    tags: [
      requestHeaders(new Headers(request.headers)),
      requestStop(request.signal),
      requestClose((graceful) => session.close({ graceful })),
    ],
  });
  session.resolve(renderLifetime).open(request);

  const lifetime = session.resolve(requestLifetime);

  try {
    const result = await next({ context: { session, signal: request.signal } });
    return {
      ...result,
      response: await (
        await session.resolve(responseBodies)
      ).hold(result.response, lifetime.finish),
    };
  } catch (error) {
    await lifetime.finish(false);
    throw error;
  }
});

/** Startup supplies the root context; all Start boundaries share this middleware. */
export const startRequests = Object.assign(
  extension({
    label: "start.requests",
    hooks: {
      async start(event) {
        await event.next();
        return { scope: event.scope };
      },
    },
  }),
  { middleware },
);

import { operation } from "@tinker/core";

/** The copied base version; it changes when this component is updated. */
export const baseVersion = "0.8.0";

export const health = operation({
