import { resource, tag } from "@tinker/core";
import type { Scope } from "@tinker/core";

/** The native middleware lends its session close to that session. */
export const requestClose = tag<(graceful: boolean) => Promise<Scope.Result>>({
  label: "request.closeOwner",
});

/** Share one close promise without joining the session's own teardown. */
export const requestLifetime = resource({
  label: "request.close",
  target: "session",
  depends: { close: requestClose.required },
  factory: ({ close }) => {
    let closed: Promise<void> | undefined;

    return {
      finish: (graceful: boolean) => {
        return (closed ??= Promise.resolve(close(graceful)).then((end) => {
          if (end.teardownErrors?.length) throw end.teardownErrors.at(0);
        }));
      },
    };
  },
});

import { tag } from "@tinker/core";

/**
 * The one way out for HTTP components send themselves; tests bind a fake (ADR 0102). Its default is
 * the real `fetch`: an effect default on the seam, as ADR 0113 allows.
 */
export const httpBackend = tag<typeof fetch>({
  label: "http.backend",
  default: (input, init) => fetch(input, init),
});

import { operation, resource } from "@tinker/core";
import { z } from "zod";

import { abortReasons, raise } from "~/components/errors";
import { backendStop, requestStop } from "~/components/requests";

import { httpBackend } from "./backend";

const requestShape = z
  .strictObject({
    url: z.url({ protocol: /^https?$/ }),
    method: z
      .string()
      .regex(/^[!#$%&'*+\-.^_`|~0-9A-Za-z]+$/)
      .toUpperCase(),
    headers: z.record(z.string(), z.string()).optional(),
    body: z.string().optional(),
  })
  .brand<"HttpRequest">();

const nameShape = z.string();
const codeShape = z.union([z.string(), z.number()]);

/** Caught native errors are not operation input; each failure field is checked on its own. */
const failureShape = z.object({
  name: z.unknown().optional(),
  code: z.unknown().optional(),
  cause: z.unknown().optional(),
});

/** Closing this session or an ancestor ends HTTP waits before graceful work drains.
 * Stop tags also end waits without closing a layer; caller cancellation keeps Core's result. */
export const http = resource({
  label: "http",
  target: "session",
  depends: {
    send: httpBackend,
    backendStop: backendStop.optional,
    requestStop: requestStop.optional,
  },
  factory: ({ send, backendStop, requestStop }, { closing, defer }) => {
    const stop = new AbortController();
    defer(() => stop.abort(abortReasons.closed));
    return {
      async send(url: string, init: RequestInit & { signal: AbortSignal }) {
        const signal = AbortSignal.any([
          init.signal,
          closing,
          stop.signal,
          ...(backendStop.present ? [backendStop.value] : []),
          ...(requestStop.present ? [requestStop.value] : []),
        ]);
        signal.throwIfAborted();
        const response = await send(url, { ...init, signal });
        return {
          status: response.status,
          headers: Object.fromEntries(
            Array.from(response.headers, ([name, value]): [string, string[]] => [
              name,
              name === "set-cookie" ? response.headers.getSetCookie() : [value],
            ]),
          ),
          body: await response.text(),
        };
      },
    };
  },
});

/** HTTP statuses are results; only sending or reading failures raise HttpRequestFailed. */
export const httpRequest = operation({
  label: "http.request",
  input: requestShape,
  depends: { http },
  run: ({ http }, { input, obs, signal }) => {
    const { url, method, headers, body } = input;
    const path = new URL(url).pathname;
    return obs.child(`http ${method} ${path}`, async (span) => {
      if (span) {
        span.attributes["http.request.method"] = method;
        span.attributes["url.path"] = path;
      }
      try {
        const response = await http.send(url, { method, headers, body, signal: signal });
        if (span) span.attributes["http.response.status_code"] = response.status;
        return response;
      } catch (cause) {
        signal.throwIfAborted();
        const failure = failureShape.safeParse(cause);
        if (!failure.success) raise("HttpRequestFailed", { method, path });

        const nested = failureShape.safeParse(failure.data.cause);
        const details = nested.success ? nested.data : failure.data;
        const name = nameShape.optional().catch(undefined);
        const code = codeShape.optional().catch(undefined);

        raise("HttpRequestFailed", {
          method,
          path,
          cause: {
            name: name.parse(details.name) ?? name.parse(failure.data.name),
            code: code.parse(details.code) ?? code.parse(failure.data.code),
          },
        });
      }
    });
  },
});

import { extension, operation, resource, tag } from "@tinker/core";

import { postgres, drizzlePostgres, drizzlePgCore, drizzleMigrator } from "./modules";
import type { Database } from "./types";

/** Where Postgres is. */
export const databaseUrl = tag<URL>({ label: "database.url" });

const migrationsFolder = "drizzle";

/** Feature code uses native PostgreSQL queries, without the driver's client field. */
export const database = resource({
  label: "database",
  depends: { url: databaseUrl, postgres, orm: drizzlePostgres },
  factory: async ({ url, postgres, orm }, { defer }): Promise<Database.Handle> => {
    const { default: pg } = postgres;
    const { drizzle } = orm;
    const client = new pg.Pool({ connectionString: url.href });
    const listeners = new Set<AbortController>();

    defer(async () => {
      for (const stop of listeners) stop.abort();
      await client.end();
    });

    return Object.assign(drizzle({ client }), {
      async listen(heard: (payload: string) => void, disconnected: () => void) {
        const listener = await client.connect();
        const notified = (message: { payload?: string }) => heard(message.payload ?? "");
        listener.on("notification", notified);
        listener.on("error", disconnected);
        listener.on("end", disconnected);

        const stop = new AbortController();
        listeners.add(stop);

        stop.signal.addEventListener(
          "abort",
          () => {
            listeners.delete(stop);
            listener.removeListener("notification", notified);
            listener.removeListener("error", disconnected);
            listener.removeListener("end", disconnected);
            listener.release(true);
          },
          { once: true },
        );

        try {
          await listener.query("LISTEN start_sync");
          return stop.abort.bind(stop);
        } catch (error) {
          stop.abort();
          throw error;
        }
      },
    });
  },
});

export const migrate = operation({
  label: "migrate",
  depends: {
    database,
    pgCore: drizzlePgCore,
    migrator: drizzleMigrator,
  },
  run: async ({ database, pgCore, migrator }) => {
    const { migrate } = pgCore;
    const { readMigrationFiles } = migrator;
    await migrate(readMigrationFiles({ migrationsFolder }), database, { migrationsFolder });
  },
});

export const databaseSetup = extension({
  label: "database.setup",
  hooks: {
    async start({ next, scope }) {
      await next();
      await scope.run(migrate);
    },
  },
});

