import { raise } from "~/components/errors";
import type { Env } from "~/components/errors";

import { databaseUrl } from "./database.server";

const appEnv = z.object({
  DATABASE_URL: z.url(),
});

/**
 * The main validates database keys once; database units receive typed tags (ADR 0113).
 * @param env - From the app's server entry; why: the keys to check and convert.
 */
export function settings(env: Env.Values) {
  const parsed = appEnv.safeParse(env);
  if (!parsed.success) {
    raise("BadSettings", {
      part: "database",
      keys: parsed.error.issues.map((issue) => issue.path.join(".")),
    });
  }

  return [databaseUrl(new URL(parsed.data.DATABASE_URL))];
}

import type { PgAsyncDatabase, PgQueryResultHKT } from "drizzle-orm/pg-core";

export declare namespace Database {
  /**
   * What the server seam's `database` gives the sync part: a drizzle Postgres database, and
   * `listen`, which calls `heard` with the payload of each `start_sync` notification until the
   * returned stop. A payload is a table name for a saved change, or `account:<id>` for a notice.
   */
  type Handle = PgAsyncDatabase<PgQueryResultHKT> & {
    listen: (
      heard: (payload: string) => void,
      disconnected: () => void,
    ) => Promise<() => void | Promise<void>>;
  };
  type Transaction = Parameters<Parameters<Handle["transaction"]>[0]>[0];
}

import { extension, isError, tag } from "@tinker/core";
import { z } from "zod";

import { raise } from "~/components/errors";
import type { Env } from "~/components/errors";

import { sendAuthMail, sessionDeleted } from "./slots";

export declare namespace Auth {
  type Settings = { origin: string; secret: string };
  type ServerPart = {
    readonly extensions: readonly (typeof authStartup)[];
    readonly settings: Env.Read;
  };
}

export const authSettings = tag<Auth.Settings>({ label: "auth.settings" });

const authEnv = z.object({
  PUBLIC_ORIGIN: z.url({ protocol: /^https?$/ }),
  AUTH_SECRET: z.string().min(32),
});

/**
 * @param env - From the command's copy of process.env; why: check auth's two keys once.
 */
export function settings(env: Env.Values) {
  const parsed = authEnv.safeParse(env);
  if (!parsed.success) {
    raise("BadSettings", {
      part: "auth",
      keys: parsed.error.issues.map((issue) => String(issue.path[0])),
    });
  }

  return authSettings({ origin: parsed.data.PUBLIC_ORIGIN, secret: parsed.data.AUTH_SECRET });
}

/** Missing hooks fail before a database or auth client starts. */
export const authStartup = extension({
  label: "auth",
  hooks: {
    async start({ resolve, next }) {
      resolve(authSettings);
      try {
        resolve(sendAuthMail);
        resolve(sessionDeleted);
      } catch (error) {
        if (isError(error, "MissingTag")) {
          error.message = `Auth startup needs "${error.payload.label}" in cmds/server.ts`;
        }
        throw error;
      }

      await next();
    },
  },
});

